/*
 * A369419  Numbers k that are neither squarefree nor prime powers such that
 *          A119288(k) <= k/A007947(k) < A053669(k) and k has a primorial
 *          kernel but is not a product of primorials.
 * https://oeis.org/A369419
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th term of { m*P(i) : i >= 2, 3 <= m < prime(i+1), m
 *            not a product of primorials } in increasing order, where P(i) =
 *            prime(1)*...*prime(i) (generated by direct search over rows i)
 * Range:     u8 n <= 3, u16 n <= 14, u32 n <= 61, u64 n <= 231, u128 n <= 875,
 *            big any n
 * Validated: standard, pass, 51 terms through n = 9105 (2026-11-10)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>

static bool A369419_isprime(unsigned x)
{
    if (x < 2) return false;
    for (unsigned d = 2; d * d <= x; d++)
        if (x % d == 0) return false;
    return true;
}

static unsigned A369419_nextprime(unsigned p)
{
    p++;
    while (!A369419_isprime(p)) p++;
    return p;
}

/* true if m is NOT a product of primorials (prime exponents not non-increasing over consecutive primes) */
static bool A369419_not_prod_primorials(unsigned m)
{
    unsigned prev = 0xFFFFFFFFu;
    unsigned p = 2;
    while (m > 1) {
        unsigned e = 0;
        while (m % p == 0) { m /= p; e++; }
        if (e > prev) return true;
        prev = e;
        p = A369419_nextprime(p);
    }
    return false;
}

seq_t a(idx_t n)
{
    idx_t count = 0;
    unsigned p = 2;
    seq_t P = 2;
    for (;;) {
        p = A369419_nextprime(p);
        P = P * (seq_t)p;
        unsigned q = A369419_nextprime(p);
        for (unsigned m = 3; m < q; m++) {
            if (A369419_not_prod_primorials(m)) {
                count++;
                if (count == n) return (seq_t)m * P;
            }
        }
    }
}
